const int pinA = 2;
const int pinB = 3;
int counter = 0;
int lastStateA;

void setup() {
  pinMode(pinA, INPUT);
  pinMode(pinB, INPUT);
  Serial.begin(9600);
  lastStateA = digitalRead(pinA);
}

void loop() {
  int stateA = digitalRead(pinA);
  if (stateA != lastStateA && stateA == 1) {
    if (digitalRead(pinB) != stateA) counter++;
    else counter--;
    Serial.print("Position: ");
    Serial.println(counter);
  }
  lastStateA = stateA;
}
